js.text:

function grid$hrbstcong(f){
  this.constructor(f);
}
grid$hrbstcong.prototype = new DirEvent();
grid$hrbstcong.prototype.afterInitFields = function(){
  var p = this._dir;
}
grid$hrbstcong.prototype.beforeInit = function(renderType){
  var fi, p = this._dir, g = p.grid(), dt = new DataTable(g.data.Tables[0]), d = p.options._ngay_den, fm = (d.getMonth() == p.options._ngay_tu.getMonth())?'dd':'dd/mm';
  p.options._weekend = []; p.options._weekend0 = []; p.options._colDays = {}
  while (d >= p.options._ngay_tu) {
    fi = p.addColumn(0, 'gio', 'gio_' + $.date(d, 'yymmdd'), $.date(d, fm), 5);
    if (d.getDay() == 0 || d.getDay() == 6) p.options._weekend.push(fi.name);
    if (d.getDay() == 0) {p.options._weekend0.push(fi.name); fi.inactivate = true;}
    p.options._colDays[fi.name] = d;
    d = $.addDays(d, -1);
  }
  p.field('gio', 0).hidden = true;
  dt.setPrimaryKey(['id', 'ma_cong']);
  if (p.options.reload == "") {
    var dtU = p.options.dtUpdate, k = dtU.count();
    while(k--) {
      var dtTemp = dt.clone(['id', 'ma_cong'], null);
      dtTemp.addColumn("N", 'gio_' + $.date(dtU.val(k, 'ngay'), 'yymmdd'));
      dtTemp.addRow([dtU.val(k, 'id'), dtU.val(k, 'ma_cong'), dtU.val(k, 'so_gio')])
      dt.update(dtTemp, 0, true);
    }
  }
}
grid$hrbstcong.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid(), dt = g.data;
  if (p.options._weekend.length) p.find("." + p.options._weekend.join(",.")).css("color", "red");
  if (p.options._weekend0.length) p.find("." + p.options._weekend0.join(",.")).css("font-weight", "700");
  if (p.options.reload != "") {
    p.options.dtUpdate = dt.clone(['id', 'ma_cong'], null); //Neu reload lai store thi tao lai bang thay doi
    p.options.dtUpdate.addColumn(["D", "N"], ["ngay", "so_gio"]);
    p.options.dtUpdate.setPrimaryKey(['id', 'ma_cong', 'ngay']);
  }
  p.find(".grid-input-field[value!='0.0']").css({"font-weight": "700"});
  p.find(".grid-input-field[value='0.0']").css({"color": "AliceBlue"});
}
grid$hrbstcong.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir, g = p.grid(), dt = g.data;
  if (c.indexOf('gio_') == 0) {
    var dtTemp = dt.clone(['id', 'ma_cong'], null);
    dtTemp.addColumn(["D", "N"], ["ngay", "so_gio"]);
    dtTemp.addRow([dt.val(r, 'id'), dt.val(r, 'ma_cong'), p.options._colDays[c], v])
    p.options.dtUpdate.update(dtTemp, 0, false, ['so_gio']);
    o.css({"font-weight": (v != 0)? "700":"", "color": (v != 0)? "":"AliceBlue"});
  }
}
grid$hrbstcong.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    case 'save':
      if (p.options.dtUpdate.count() == 0) {
        $.showToast(p.msg('noChange'));
        return false;
      }
      var m = new Memvars();
      m.val('bstcong', 'T', p.options.dtUpdate.sqlval(), 'hrbstcong'); //Khai bao field EX de ko request len server cho nhe
      p.request('Save', '', m, function(p, d, run) {
        if (run) p._refresh(true);
      });
      return false;
    default:
      break;
  }
  return true;
}
